// === Tab: mySketch ===
let WIDTH = 1024;
let HEIGHT = WIDTH*.75;
let NUM_PARTICLES = 100;
let VELOC = 10;
let MAX_EDAD = 100;
let VELOC_EDAD = .2;
let ROTACION_VAL = .015;
let VELOC_MIN = 0;
let FACTOR_DIR = 2;
let BORDE = WIDTH / 4;

ArrayList<Particula> particulas = new ArrayList<Particula>();

function setup() {
  createCanvas(1024, 768);
  smooth();
  background(0);
  let semilla = int(random(100000));

  randomSeed(semilla);

	for (i = 0; i < NUM_PARTICLES; i++) {
    particulas.add(new Particula(
          random(0 + BORDE, WIDTH - BORDE),
          random(0 + BORDE, HEIGHT - BORDE),
          random(-VELOC / FACTOR_DIR, VELOC / FACTOR_DIR),
          random(-VELOC / FACTOR_DIR, VELOC / FACTOR_DIR)));
  }
}

function draw() {
  for (let p of particulas) {
    p.update();
    p.display();
  }
}

function mousePressed() {
  save('pix.jpg');
}

class Particula {
  x;
  y;
  vel;
  prevx;
  prevy;
  vida;
  edad;

  constructor(x, y, velx, vely) {
    this.x = x;
    this.y = y;
    this.vel = new PVector(velx, vely);
    this.prevx = x;
    this.prevy = y;
    this.vida = true;
    this.edad = 0;
    if (abs(vel.x) < VELOC_MIN && abs(vel.y) < VELOC_MIN) {
      vida = false;
    }
  }

  function update() {
    if (!vida) {
      return;
    }
    prevx = x;
    prevy = y;
    x += random(-VELOC, VELOC);
    y += random(-VELOC, VELOC);
    x += vel.x;
    y += vel.y;
    vel.rotate(ROTACION_VAL);
    edad += VELOC_EDAD;
    if (edad > MAX_EDAD) {
      vida = false;
    }
  }

  function display() {
    stroke(map(edad, 0, MAX_EDAD, 0, 255), 0, 255); //R, G, B
//		map(edad, 0, MAX_EDAD, 0, 255) // redistribuir un rango
    line(prevx, prevy, x, y);
  }

}

